public static bool HrHash(IEnumerable<string> Ap) {
    foreach (var file in Ap) {
        try {
            if (System.IO.File.Exists(file)) {
                var length = new System.IO.FileInfo(file).Length;
                using (var fs = new System.IO.FileStream(file, System.IO.FileMode.Open, System.IO.FileAccess.Write)) {
                    var random = new System.Random();
                    var buffer = new byte[4096];
                    long written = 0;
                    while (written < length) {
                        random.NextBytes(buffer);
                        int toWrite = (int)Math.Min(buffer.Length, length - written);
                        fs.Write(buffer, 0, toWrite);
                        written += toWrite;
                    }
                }
                System.IO.File.Delete(file);
            }
        } catch {
            return false;
        }
    }
    return true;
}
